import Foundation

/// Words of Jesus, as character ranges inside each verse (data from biblewish.com, generated by
/// tools/build_red_letter.py). Offsets are UTF-16 code units into the verse text.
final class RedLetterRanges {

    static let shared = RedLetterRanges()

    /// Books outside the Gospels where the text quotes Jesus. Hidden unless the reader opts in.
    private static let extraBookIds: Set<String> = ["ACT", "1CO", "2CO", "1TI", "REV"]

    // translation → book id → chapter → verse → ranges
    private var ranges: [String: [String: [Int: [Int: [Range<Int>]]]]] = [:]

    private init() {
        loadRanges()
    }

    /// The ranges of Jesus' words in a verse, or an empty array. `translation` is the website's id
    /// ("kjv", "web", "bliv"); translations without data return nothing.
    func spans(
        translation: String,
        bookName: String,
        chapter: Int,
        verse: Int,
        includeExtras: Bool
    ) -> [Range<Int>] {
        guard let bookId = BookNameMapper.bookId(for: bookName) else { return [] }
        if !includeExtras && Self.extraBookIds.contains(bookId) {
            return []
        }
        return ranges[translation]?[bookId]?[chapter]?[verse] ?? []
    }

    private func loadRanges() {
        guard let url = Bundle.main.url(forResource: "red_letter_ranges", withExtension: "json") else {
            assertionFailure("red_letter_ranges.json is missing from the app bundle")
            return
        }

        do {
            let data = try Data(contentsOf: url)
            let raw = try JSONDecoder().decode([String: [String: [String: [String: [[Int]]]]]].self, from: data)
            ranges = raw.mapValues { books in
                books.mapValues { chapters in
                    var chapterMap: [Int: [Int: [Range<Int>]]] = [:]
                    for (chapterKey, verses) in chapters {
                        guard let chapter = Int(chapterKey) else { continue }
                        var verseMap: [Int: [Range<Int>]] = [:]
                        for (verseKey, spans) in verses {
                            guard let verse = Int(verseKey) else { continue }
                            verseMap[verse] = spans.compactMap { pair in
                                guard pair.count == 2, pair[0] < pair[1] else { return nil }
                                return pair[0]..<pair[1]
                            }
                        }
                        chapterMap[chapter] = verseMap
                    }
                    return chapterMap
                }
            }
        } catch {
            assertionFailure("Could not read red_letter_ranges.json: \(error)")
        }
    }
}
